css:
/* Feature tabs: a heading, then intro, numbered tabs and a list on the left and a photo on the right.
   With no script (and on the Design canvas) every panel is in flow, one under the other; the script
   adds .is-tabs and shows one at a time. */
[data-bz-node="ft-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="feature-tabs"] .bz-block { padding-block: 0; }
[data-bz-section="feature-tabs"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-row"] { margin-top: 52px; align-items: center; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-left"] { max-width: 570px; margin-left: 81px; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-intro"] .bz-text p { margin: 0 0 40px; padding-inline: 26px; font: 400 1.15rem / 1.55 var(--font-body); color: #333; max-width: none; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-tabset"] { background: #ebf7ff; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-tabset-col"] { padding: 29px 26px 29px; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-tabs"] { display: flex; gap: 0; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-tabs"] > .bz-col { flex: 0 0 auto; grid-column: auto; min-width: 56px; }
[data-bz-section="feature-tabs"] [data-bz-node^="ft-tab-label"] .bz-text p { margin: 0; padding: 18px 0 16px; text-align: center; font: 400 0.8rem / 1 var(--font-body); color: #003550; cursor: pointer; border: 1px solid transparent; border-bottom: 0; }
[data-bz-section="feature-tabs"] .is-tab-active [data-bz-node^="ft-tab-label"] .bz-text p, [data-bz-section="feature-tabs"] [data-bz-node="ft-tabs"] > .bz-col:first-child:not(.is-tabbed) [data-bz-node^="ft-tab-label"] .bz-text p { border-color: #003550; background: #fff; position: relative; z-index: 1; margin-bottom: -1px; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-panels"] { border: 1px solid #003550; background: #fff; padding: 28px 30px 30px; margin-top: 0; }
[data-bz-section="feature-tabs"] [data-bz-node^="ft-panel-text"] .bz-text p { margin: 0; font: 400 0.8rem / 1.5 var(--font-body); color: #333; max-width: none; }
[data-bz-section="feature-tabs"] .is-tabs [data-bz-node="ft-panels"] > .bz-col:not(.is-tab-active) { display: none; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-know"] { margin-top: 40px; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-know"] .bz-text p { margin: 0 0 16px; padding-inline: 26px; font: 700 0.8rem / 1.2 var(--font-body); color: #000; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-list"] .bz-text p { position: relative; margin: 0 0 4px; padding: 0 112px 0 28px; font: 400 0.88rem / 1.6 var(--font-body); color: #333; max-width: none; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-list"] .bz-text p::before { content: ""; position: absolute; left: 10px; top: 0.7em; width: 4px; height: 4px; border-radius: 50%; background: #333; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-photo"] .bz-figure { margin: 0; text-align: center; }
[data-bz-section="feature-tabs"] [data-bz-node="ft-photo"] img { display: inline-block; width: 100%; max-width: 600px; height: auto; border-radius: 0; }
@media (max-width: 1100px) { [data-bz-section="feature-tabs"] [data-bz-node="ft-left"] { margin-left: 0; max-width: none; } [data-bz-section="feature-tabs"] [data-bz-node="ft-intro"] .bz-text p, [data-bz-section="feature-tabs"] [data-bz-node="ft-know"] .bz-text p { padding-inline: 0; } [data-bz-section="feature-tabs"] [data-bz-node="ft-list"] .bz-text p { padding-right: 0; } [data-bz-section="feature-tabs"] [data-bz-node="ft-tabset-col"] { padding: 20px 14px; } [data-bz-section="feature-tabs"] [data-bz-node="ft-tabs"] { flex-wrap: wrap; } }
@media (max-width: 640px) { [data-bz-section="feature-tabs"] h2 { font-size: 1.5rem; } }

js:
/* Feature tabs: the numbered tabs show one panel at a time. There is no behaviour for numbered tabs,
   so this is the whole of it: click or arrow keys, one panel visible, the matching tab marked. */
(function () {
  document.querySelectorAll('[data-bz-section="feature-tabs"]').forEach(function (root) {
    if (root.__bzTabs) return;
    root.__bzTabs = true;
    var tabs = root.querySelectorAll('[data-bz-node="ft-tabs"] > .bz-col');
    var panels = root.querySelectorAll('[data-bz-node="ft-panels"] > .bz-col');
    if (!tabs.length || tabs.length !== panels.length) return;
    var list = root.querySelector('[data-bz-node="ft-tabs"]');
    list.setAttribute('role', 'tablist');
    function show(i) {
      tabs.forEach(function (t, j) {
        t.classList.add('is-tabbed');
        t.classList.toggle('is-tab-active', i === j);
        t.setAttribute('aria-selected', i === j ? 'true' : 'false');
        t.setAttribute('tabindex', i === j ? '0' : '-1');
        panels[j].classList.toggle('is-tab-active', i === j);
      });
    }
    root.classList.add('is-tabs');
    tabs.forEach(function (t, i) {
      t.setAttribute('role', 'tab');
      t.addEventListener('click', function () { show(i); });
      t.addEventListener('keydown', function (e) {
        var n = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : -1;
        if (n >= 0 && n < tabs.length) { show(n); tabs[n].focus(); e.preventDefault(); }
      });
    });
    show(0);
  });
})();
